import{_ as s,l as i,o as e,c as l,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"简单类型 λ 演算","description":"","frontmatter":{"title":"简单类型 λ 演算","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simply-typed-lambda.md","filePath":"cs/simply-typed-lambda.md","lastUpdated":1789023840000}'),h={name:"cs/simply-typed-lambda.md"};function m(u,a,_,T,f,A){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="简单类型-λ-演算" tabindex="-1">简单类型 λ 演算 <a class="header-anchor" href="#简单类型-λ-演算" aria-label="Permalink to &quot;简单类型 λ 演算&quot;">​</a></h1><div class="epigraph"><p>给无类型项加上函数类型 $\\tau\\to\\tau&#39;$；井型项有范式。类型是静态的过滤器，不是又一套 β。</p><footer>—— 据 Church, A Formulation of the Simple Theory of Types, 1940；Pierce, Types and Programming Languages 整理</footer></div><p>上一课<a href="/cs/source-encoding-lexing">源码编码</a>收束前端课序。主干已有<a href="/cs/lambda-calculus">λ 演算</a>与<a href="/cs/typecheck">类型检查</a>。本课是类型系统单元的第一课：缺口不是再定义 β，而是<strong>简单类型</strong>（STLC）——判断 \\(\\Gamma\\vdash t:\\tau\\)，以及它相对无类型 λ 失去了什么（不全、没有 <code>Y</code>）。后课默认已经读完本课的箭头类型与上下文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无类型 λ 图灵完全，也没有「参数该是函数还是整数」的静态拒绝。<a href="/cs/proof-assistants">证明助手</a>点过 Curry–Howard，那里要依值；本课先停在简单类型。规则：变量看 Γ，抽象引入 \\(x:\\tau\\)，应用要求左件是 \\(\\tau\\to\\tau&#39;\\)。缺口是<strong>这套判断</strong>，不是词法。</p><p>规范化：良型 STLC 强规范化（无类型循环项不可型）。因此 STLC 不是全部可计算——要递归须另加语言结构或后课多态/依值。</p><h3 id="不是机器里的函数指针-abi" tabindex="-1">\\(\\to\\) 不是机器里的函数指针 ABI <a class="header-anchor" href="#不是机器里的函数指针-abi" aria-label="Permalink to &quot;$\\to$ 不是机器里的函数指针 ABI&quot;">​</a></h3><p>类型是语法对象。擦除后仍可 β。本课不谈闭包转换，那在运行时单元。也不谈 <a href="/cs/typecheck">C 函数类型</a> 的声明符细节。</p><p><span class="marginnote">Church 1940。Pierce TAPL 第 9 章是本课地图。Appel 用类型保证 IR 的某些不变量。本课不引入积、和、递归类型——后课 ADT 再加。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写一小组规则。证明：若 \\(\\Gamma\\vdash t:\\tau\\) 且 \\(t\\to_\\beta t&#39;\\) 则 \\(\\Gamma\\vdash t&#39;:\\tau\\)（保持）；良型项可再归约或已是值（进展）——完整定理在<a href="/cs/type-soundness">健全性</a>课，本课只要规则形状。</p>',11)),(e(),d(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E6%97%A0%E7%B1%BB%E5%9E%8B%E9%A1%B9%22%5D%20--%3E%20ANN%5B%22%E5%8A%A0%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20ANN%20--%3E%20CHK%5B%22%CE%93%20%E2%8A%A2%20t%20%3A%20%CF%84%22%5D%0A%20%20CHK%20--%3E%20NF%5B%22%E8%89%AF%E5%9E%8B%E5%88%99%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与主干类型检查：那里是语言表面语法；这里是核心演算。表面语言的检查应能阐述到 STLC 或其后继。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>类型擦除：运行不看 \\(\\tau\\)。简单类型没有多态：恒等函数必须钉死参数类型，或靠后课 HM 的方案。<code>Y</code> 无简单类型，故不能在 STLC 里写任意递归。</p><p>Church 数字在 STLC 里可型，但足够强的迭代往往需要递归类型或多态。点名即可。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写算法 W，不引入子类型。后课默认：箭头类型 + 上下文是核心判断。下一课 Hindley–Milner：从「注解写满」到「主类型」。</p><p>不要把 STLC 当 Python 的类型提示；这里拒绝不能型的应用，不是运行时 <code>TypeError</code>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STLC：\\(\\Gamma\\vdash t:\\tau\\)，箭头是唯一构造子（本课）。</li><li>良型项规范化；图灵完全被拿掉。</li><li>擦除后仍是 λ；类型只在静态。</li><li>出处：Church, 1940；Pierce, TAPL。</li></ul>',9))])}const b=s(h,[["render",m]]);export{E as __pageData,b as default};
